import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int h = 1;
        while (h < n / 3) {
            h = 3 * h + 1;
        }
        StringBuilder sb = new StringBuilder();
        while (h >= 1) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(h);
            h /= 3;
        }
        System.out.println(sb);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int h = 1;
    while (h < n / 3) {
        h = 3 * h + 1;
    }
    while (h >= 1) {
        cout << h;
        h /= 3;
        if (h >= 1) {
            cout << " ";
        }
    }
    cout << endl;
    return 0;
}
